    return pd.read_csv(path, dtype=str)

def process(metroFraud2024, floridaMsaFraud) -> pd.DataFrame:
    import pandas as pd
    import re

    def norm(s):
        if s is None:
            return ''
        s = str(s)
        s = s.strip().lower()
        s = re.sub(r'\s+', ' ', s)
        s = s.replace('–', '-').replace('—', '-').replace('‑', '-').replace('−', '-')
        return s

    target = norm('Miami-Fort Lauderdale-West Palm Beach')

    def find_area_col(df):
        # common candidates
        for c in df.columns:
            cn = norm(c)
            if cn in {'metropolitan area', 'metro area', 'metropolitan statistical area', 'msa', 'metro', 'area'}:
                return c
        # fallback: any column containing these tokens
        for c in df.columns:
            cn = norm(c)
            if ('metropolitan' in cn and 'area' in cn) or cn == 'msa':
                return c
        return None

    def find_count_col(df):
        # prefer explicit report count
        for c in df.columns:
            cn = norm(c)
            if 'report' in cn and 'count' in cn:
                return c
        # then any total reports
        for c in df.columns:
            cn = norm(c)
            if cn in {'reports', 'total reports', 'number of reports', 'report'}:
                return c
        # if exactly one numeric-like column besides ids
        return None

    def to_int(x):
        if pd.isna(x):
            return None
        s = str(x)
        s = re.sub(r'[^0-9]', '', s)
        if s == '':
            return None
        return int(s)

    def extract_count(df):
        area_col = find_area_col(df)
        if area_col is None:
            raise ValueError('Could not identify area column')
        subset = df[df[area_col].map(norm) == target].copy()
        if subset.empty:
            # try contains match
            subset = df[df[area_col].map(norm).str.contains(target, na=False)].copy()
        if subset.empty:
            raise ValueError('Target metro not found')

        count_col = find_count_col(df)
        if count_col is None:
            # pick first column that parses to int for at least one row
            candidates = []
            for c in df.columns:
                if c == area_col:
                    continue
                vals = subset[c].map(to_int)
                if vals.notna().any():
                    candidates.append((c, vals.notna().sum()))
            if not candidates:
                raise ValueError('No numeric count column found')
            # choose column with most parsable ints
            count_col = sorted(candidates, key=lambda t: t[1], reverse=True)[0][0]

        vals = subset[count_col].map(to_int).dropna().unique().tolist()
        if len(vals) == 0:
            raise ValueError('No count values parsed')
        if len(vals) > 1:
            # if multiple rows, require all equal
            if len(set(vals)) != 1:
                raise ValueError('Multiple differing counts in same file')
        return int(vals[0]), area_col, count_col, len(subset)

    metroCount, mAreaCol, mCountCol, mN = extract_count(metroFraud2024)
    flCount, fAreaCol, fCountCol, fN = extract_count(floridaMsaFraud)

    consistent = (metroCount == flCount)

    return pd.DataFrame([{
        'consistent': bool(consistent),
        'metroCount': metroCount,
        'floridaCount': flCount,
        'metroAreaCol': mAreaCol,
        'metroCountCol': mCountCol,
        'metroRowsMatched': mN,
        'flAreaCol': fAreaCol,
        'flCountCol': fCountCol,
        'flRowsMatched': fN,
    }])

def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Metropolitan_Areas_Fraud_and_Other_Reports.csv'
    # Try common encodings for FTC CSN files which may include non-UTF8 characters.
    try:
        return pd.read_csv(path, dtype=str, encoding='utf-8')
    except UnicodeDecodeError:
        return pd.read_csv(path, dtype=str, encoding='latin-1')
